        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{if(!$this->query('SELECT id FROM jingo_supply_lots WHERE id=?',[$input['lotId']])->fetchColumn())throw new HttpError(404,'Không tìm thấy nguồn.');$total=(int)$this->query('SELECT COUNT(*) FROM jingo_ticket_stock s WHERE '.$where,$args)->fetchColumn();$page=min((int)$page,max(1,(int)ceil($total/50)));$offset=($page-1)*50;$rows=$this->query('SELECT s.id,s.code,s.status,s.version,s.reason,s.created_at,s.order_id,o.code AS order_code FROM jingo_ticket_stock s LEFT JOIN jingo_orders o ON o.id=s.order_id WHERE '.$where." ORDER BY s.created_at,s.id LIMIT 50 OFFSET $offset",$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row)$row['version']=(int)$row['version'];unset($row);$counts=['AVAILABLE'=>0,'BLOCKED'=>0,'ISSUED'=>0];foreach($this->query('SELECT status,COUNT(*) AS quantity FROM jingo_ticket_stock WHERE lot_id=? GROUP BY status',[$input['lotId']])->fetchAll(PDO::FETCH_ASSOC) as $count)$counts[$count['status']]=(int)$count['quantity'];$this->db->commit();return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>50,'counts'=>$counts];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
