        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{$this->staffGuard($id,$staffId,false);$order=$this->query('SELECT * FROM jingo_orders WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if(!$order)throw new HttpError(404,'Không tìm thấy đơn.');$this->staffOrder($order,$staffId);$data=$this->groups($order);if($staffId!==null)$data=array_map(fn($g)=>array_intersect_key($g,array_flip(['lotId','customerType','capacity','codes'])),$data);$this->db->commit();return ['data'=>$data];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function deliver(string $id,array $input,string $actor,?string $staffId=null):array
