        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$this->staffGuard($id,$staffId,true);if($staffId!==null)$actor='pos-user:'.$staffId;$order=$this->query('SELECT * FROM jingo_orders WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$order)throw new HttpError(404,'Không tìm thấy đơn.');$this->staffOrder($order,$staffId);$prior=$this->query('SELECT request_hash FROM jingo_order_actions WHERE id=?',[$input['requestId']])->fetchColumn();if($prior!==false){if(!hash_equals($prior,$hash))throw new HttpError(409,'Mã thao tác đã dùng.');$this->db->commit();return ['ok'=>true,'duplicate'=>true];}if((int)$order['version']!==$input['version'])throw new HttpError(409,'Đơn đã thay đổi. Tải lại trước khi giao.');$this->lock();$groups=$this->groups($order);$scopes=[];foreach($groups as $group)$scopes[$group['lotId']]=$group['capacity'];$planned=[];$chosen=[];foreach($input['stockIds'] as $sid){$stock=$this->query('SELECT lot_id,code,status FROM jingo_ticket_stock WHERE id=? FOR UPDATE',[$sid])->fetch(PDO::FETCH_ASSOC);$item=$stock&&$stock['status']==='AVAILABLE'&&isset($scopes[$stock['lot_id']])?['code'=>$stock['code'],'lotId'=>$stock['lot_id'],'capacity'=>$scopes[$stock['lot_id']]]:null;if(!$item)throw new HttpError(409,'Mã không còn sẵn hoặc không thuộc phần nguồn đã phân bổ đúng gói/ngày.');$planned[$item['lotId']]=($planned[$item['lotId']] ?? 0)+1;if($planned[$item['lotId']]>$item['capacity'])throw new HttpError(409,'Số mã vượt phần nguồn đã phân bổ.');if($this->query('SELECT id FROM jingo_order_tickets WHERE code_hash=?',[hash('sha256',$item['code'])])->fetchColumn())throw new HttpError(409,'Có mã vé đã được giao.');$chosen[$sid]=$item;}$snapshot=json_decode($order['snapshot'],true,512,JSON_THROW_ON_ERROR);$needed=array_sum(array_column($snapshot['lines'],'quantity'));$issued=(int)$this->query('SELECT COALESCE(SUM(covers),0) FROM jingo_order_tickets WHERE order_id=?',[$id])->fetchColumn();if($issued+count($chos